static int best;

static int gain(struct TreeNode *node) {
  if (node == NULL) return 0;
  int left = gain(node->left);
  if (left < 0) left = 0;
  int right = gain(node->right);
  if (right < 0) right = 0;
  int through = node->val + left + right;
  if (through > best) best = through;
  return node->val + (left > right ? left : right);
}

int maxPathSum(struct TreeNode *root) {
  best = INT_MIN;
  gain(root);
  return best;
}

class Solution {
  int best;

  int gain(TreeNode *node) {
    if (!node) return 0;
    int left = max(0, gain(node->left));
    int right = max(0, gain(node->right));
    best = max(best, node->val + left + right);
    return node->val + max(left, right);
  }

public:
  int maxPathSum(TreeNode *root) {
    best = INT_MIN;
    gain(root);
    return best;
  }
};

func maxPathSum(root *TreeNode) int {
	best := math.MinInt32
	var gain func(node *TreeNode) int
	gain = func(node *TreeNode) int {
		if node == nil {
			return 0
		}
		left := gain(node.Left)
		if left < 0 {
			left = 0
		}
		right := gain(node.Right)
		if right < 0 {
			right = 0
		}
		if node.Val+left+right > best {
			best = node.Val + left + right
		}
		if left > right {
			return node.Val + left
		}
		return node.Val + right
	}
	gain(root)
	return best
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private int best;

  private int gain(TreeNode node) {
    if (node == null) {
      return 0;
    }
    int left = Math.max(0, gain(node.left));
    int right = Math.max(0, gain(node.right));
    best = Math.max(best, node.val + left + right);
    return node.val + Math.max(left, right);
  }

  public int maxPathSum(TreeNode root) {
    best = Integer.MIN_VALUE;
    gain(root);
    return best;
  }
}

class Solution:
    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        best = float("-inf")

        def gain(node):
            nonlocal best
            if node is None:
                return 0
            left = max(0, gain(node.left))
            right = max(0, gain(node.right))
            best = max(best, node.val + left + right)
            return node.val + max(left, right)

        gain(root)
        return best

impl Solution {
  pub fn max_path_sum(root: Option<Box<TreeNode>>) -> i32 {
    fn gain(node: &Option<Box<TreeNode>>, best: &mut i32) -> i32 {
      match node {
        None => 0,
        Some(n) => {
          let left = gain(&n.left, best).max(0);
          let right = gain(&n.right, best).max(0);
          *best = (*best).max(n.val + left + right);
          n.val + left.max(right)
        }
      }
    }

    let mut best = i32::MIN;
    gain(&root, &mut best);
    best
  }
}

const maxPathSum = (root: TreeNode | null): number => {
  let best = -Infinity;
  const gain = (node: TreeNode | null): number => {
    if (node === null) return 0;
    const left = Math.max(0, gain(node.left));
    const right = Math.max(0, gain(node.right));
    best = Math.max(best, node.val + left + right);
    return node.val + Math.max(left, right);
  };
  gain(root);
  return best;
};
